@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#101619;--panel:#192125;--panel2:#1d282c;--line:#2a373a;--muted:#879497;--white:#f3f5ed;--lime:#d5fa63;--orange:#f4a66a;--teal:#69d4c2;--red:#ee7975;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}*{box-sizing:border-box}html{background:var(--bg);color:var(--white);font-family:var(--sans);min-height:100%;-webkit-tap-highlight-color:transparent}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 42% -20%,#26363a 0,transparent 55%),var(--bg)}button{font:inherit;color:inherit;cursor:pointer}.game-shell{max-width:1450px;margin:0 auto;padding:0 40px 18px}.topbar{height:80px;display:flex;align-items:center;border-bottom:1px solid #ffffff0f;position:relative}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--white)}.brand-mark{width:37px;height:37px;border:1px solid #d5fa6385;border-radius:11px;display:grid;place-items:center;font-size:23px;font-weight:800;color:var(--lime);letter-spacing:-3px;padding-right:3px}.brand-mark span{color:white}.brand-name{font-size:9px;line-height:1.24;letter-spacing:1.6px}.brand-name b{font-size:10px}.season{position:absolute;left:50%;transform:translateX(-50%);font:10px var(--mono);letter-spacing:1.1px;color:#c2cbca;display:flex;align-items:center;gap:11px}.season i{color:#506064;font-style:normal}.live-dot,.map-live i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 9px #d5fa6380}.top-actions{margin-left:auto;display:flex;gap:9px}.icon-btn{width:34px;height:34px;background:#1a2428;border:1px solid var(--line);border-radius:50%;font-size:15px;color:#b8c2c0;transition:.2s}.icon-btn:hover{color:var(--lime);border-color:#d5fa6380}.dashboard{display:grid;grid-template-columns:minmax(0,1.66fr) minmax(320px,.84fr);gap:20px;padding-top:22px;align-items:start}.panel{background:linear-gradient(145deg,#1a2428,#172024);border:1px solid #2b383b;border-radius:14px;box-shadow:0 16px 35px #05090b30}.city-panel{padding:21px 22px 18px;min-width:0}.city-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.eyebrow{font:9px var(--mono);letter-spacing:1.6px;color:#95a2a3}.city-head h1{font-size:32px;line-height:1.1;margin:7px 0 0;font-weight:700;letter-spacing:-1.6px}.city-head h1 span{color:var(--lime)}.weather{display:flex;gap:9px;align-items:center;font:9px/1.6 var(--mono);letter-spacing:.5px;color:#cad2ce}.weather-icon{font-size:24px;color:#f2c17c}.weather small{font-size:8px;color:#829191}.map-wrap{height:clamp(310px,39vw,460px);position:relative;overflow:hidden;border:1px solid #374345;border-radius:9px;background:#19262a}.map-wrap:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#07101455,transparent 20%,transparent 78%,#08111355)}#city-map{width:100%;height:100%;display:block;touch-action:manipulation}.map-overlay{position:absolute;top:14px;left:16px;right:16px;display:flex;justify-content:space-between;align-items:center;pointer-events:none}.map-live,.map-hint,.map-legend{font:8px var(--mono);letter-spacing:1px;color:#c9d2cd}.map-live{display:flex;align-items:center;gap:7px}.map-live i{width:5px;height:5px}.map-hint{color:#9ba9a6}.map-legend{position:absolute;left:15px;bottom:13px;display:flex;gap:15px;font-size:7px;color:#d0d5cf}.map-legend i{width:7px;height:7px;display:inline-block;border-radius:2px;margin-right:5px;vertical-align:-1px}.legend-player{background:var(--lime)}.legend-rival{background:var(--orange)}.district-strip{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:12px 0 13px}.district-tab{background:#1c272b;border:1px solid #2a383b;border-radius:7px;padding:8px 7px;text-align:left;min-width:0;transition:.18s}.district-tab:hover{background:#273438}.district-tab.active{border-color:#d5fa6380;background:#283329}.district-tab strong{display:block;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:700}.district-tab span{font:8px var(--mono);color:#829091;display:block;margin-top:4px}.district-tab.active span{color:var(--lime)}.district-detail{min-height:49px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #ffffff0c;padding-top:11px;gap:12px}.district-copy{min-width:0}.district-copy strong{font-size:11px}.district-copy p{font-size:9px;color:#93a09f;margin:3px 0 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.district-stats{display:flex;gap:14px;flex-shrink:0}.district-stats span{font:8px var(--mono);color:#849291}.district-stats b{color:#edf1e8;font-weight:500}.side-column{display:flex;flex-direction:column;gap:14px}.resources-panel,.action-panel,.bulletin-panel{padding:17px 17px 15px}.section-title{font:9px var(--mono);letter-spacing:1.1px;color:#d2d9d3;display:flex;align-items:center;justify-content:space-between}.tiny-tag{border:1px solid #364447;border-radius:4px;padding:4px 6px;font-size:7px;color:#91a09e;letter-spacing:.6px}.resource-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:15px}.resource{background:#202b2f;border:1px solid #2c393b;padding:9px 9px 8px;border-radius:7px;min-height:61px}.resource-label{font:7px var(--mono);color:#94a19f;letter-spacing:.55px;display:flex;align-items:center;gap:5px}.resource-label i{font-style:normal;font-size:11px}.resource-value{font-size:19px;font-weight:700;line-height:1.25;margin-top:4px;letter-spacing:-.7px}.resource-value small{font:8px var(--mono);color:#91a09d;letter-spacing:0;margin-left:3px}.heat-row{margin-top:14px;display:flex;align-items:center;justify-content:space-between;gap:10px}.heat-row>div:first-child{display:flex;align-items:center;gap:7px}.heat-label{font:8px var(--mono);letter-spacing:.6px;color:#95a19e}.heat-row b{font:9px var(--mono);color:var(--lime)}.heat-meter{width:74px;height:4px;background:#344044;border-radius:5px;overflow:hidden}.heat-meter i{display:block;height:100%;width:18%;background:var(--lime);border-radius:5px;transition:width .3s,background .3s}.action-list{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:13px 0 10px}.action-btn{display:flex;align-items:center;gap:8px;padding:9px 9px;background:#202b2f;border:1px solid #2e3b3e;border-radius:7px;text-align:left;transition:.17s;min-height:48px}.action-btn:hover:not(:disabled){border-color:#91ad52;background:#283330;transform:translateY(-1px)}.action-btn:disabled{opacity:.42;cursor:not-allowed}.action-icon{font-size:15px;line-height:1}.action-text{min-width:0}.action-text b{font-size:9px;display:block;white-space:nowrap}.action-text small{font:7px var(--mono);color:#899694;display:block;margin-top:3px;white-space:nowrap}.advance-btn{width:100%;display:flex;justify-content:space-between;align-items:center;border:0;border-radius:7px;background:var(--lime);color:#18211b;padding:11px 13px;font-size:10px;font-weight:800;letter-spacing:1px;box-shadow:0 4px 16px #d5fa6314;transition:.2s}.advance-btn:hover{background:#e2ff83;transform:translateY(-1px)}.advance-btn b{font-size:17px;line-height:10px}.turn-note{text-align:center;color:#83918f;font-size:8px;line-height:1.55;margin-top:8px}.log-list{margin-top:10px;display:flex;flex-direction:column;gap:8px}.log-entry{display:grid;grid-template-columns:8px 1fr auto;align-items:start;gap:7px;font-size:8px;line-height:1.45;color:#bec8c2}.log-entry i{width:5px;height:5px;border-radius:50%;background:var(--teal);margin-top:4px}.log-entry:nth-child(2) i{background:var(--orange)}.log-entry:nth-child(3) i{background:#a98cf0}.log-entry small{font:7px var(--mono);color:#788785;white-space:nowrap}.footer{display:flex;justify-content:space-between;color:#697876;font:7px var(--mono);letter-spacing:.75px;padding:14px 2px 3px}.footer i{font-style:normal;color:var(--lime);padding:0 3px}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);background:#d5fa63;color:#19221b;font-size:11px;font-weight:700;padding:11px 16px;border-radius:7px;box-shadow:0 8px 30px #0006;opacity:0;pointer-events:none;transition:.25s;z-index:5;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#080e11c9;backdrop-filter:blur(8px);display:grid;place-items:center;padding:20px;z-index:10}.modal-backdrop[hidden]{display:none}.modal{width:min(480px,100%);padding:31px;position:relative}.modal-close{position:absolute;right:15px;top:13px;border:0;background:none;color:#a9b5b2;font-size:25px}.modal h2{font-size:27px;line-height:1.2;letter-spacing:-1px;margin:10px 0}.modal h2 span{color:var(--lime)}.modal>p{font-size:12px;line-height:1.7;color:#9eadaa;margin:10px 0 20px}.guide-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:22px}.guide-grid div{background:#202b2f;padding:11px;border-radius:6px;display:flex;flex-direction:column;gap:5px}.guide-grid b{font:8px var(--mono);color:var(--lime);letter-spacing:.5px}.guide-grid span{font-size:9px;line-height:1.5;color:#aab5b0}.primary-btn{width:100%;padding:12px 14px;border:0;border-radius:6px;background:var(--lime);color:#19211b;font-size:10px;font-weight:800;letter-spacing:1px;display:flex;justify-content:space-between}.primary-btn span{font-size:16px;line-height:10px}
@media(max-width:900px){.game-shell{padding:0 20px 15px}.dashboard{grid-template-columns:minmax(0,1.25fr) minmax(290px,.85fr);gap:13px}.city-panel{padding:17px}.map-wrap{height:360px}.resources-panel,.action-panel,.bulletin-panel{padding:14px}.resource{padding:8px 6px}.resource-value{font-size:17px}}
@media(max-width:700px){.game-shell{padding:0 12px calc(13px + env(safe-area-inset-bottom))}.topbar{height:64px}.brand-mark{width:32px;height:32px;border-radius:9px}.season{font-size:8px;gap:6px;letter-spacing:.5px;left:52%}.icon-btn{width:31px;height:31px}.dashboard{grid-template-columns:1fr;gap:11px;padding-top:12px}.city-panel{padding:14px 12px 12px}.city-head{margin-bottom:11px}.city-head h1{font-size:27px}.weather{font-size:8px}.map-wrap{height:clamp(270px,72vw,390px)}.map-overlay{top:11px;left:11px;right:11px}.map-hint{font-size:7px}.map-legend{left:10px;bottom:10px}.district-strip{gap:4px;margin:9px 0 10px}.district-tab{padding:7px 5px}.district-tab strong{font-size:8px}.district-tab span{font-size:7px}.district-detail{padding-top:9px}.district-stats{gap:9px}.district-copy p{max-width:220px}.side-column{display:grid;grid-template-columns:1fr 1fr;gap:10px}.resources-panel{grid-column:1/-1}.bulletin-panel{grid-column:1/-1;order:3}.action-panel,.resources-panel,.bulletin-panel{padding:13px}.resource-grid{margin-top:11px}.resource{min-height:55px}.resource-value{font-size:18px}.heat-row{margin-top:10px}.action-list{margin-top:10px;gap:6px}.action-btn{padding:8px 6px;gap:6px;min-height:44px}.action-text b{font-size:8px}.action-text small{font-size:6px}.action-icon{font-size:13px}.advance-btn{padding:10px}.turn-note{font-size:7px}.log-list{display:grid;grid-template-columns:1fr 1fr;gap:7px 10px}.log-entry{font-size:7px;grid-template-columns:7px 1fr auto}.footer{font-size:6px;padding-top:11px}.modal{padding:25px 20px}.modal h2{font-size:23px}}
@media(max-width:390px){.season{position:static;transform:none;margin-left:auto;margin-right:12px}.top-actions{margin-left:0}.district-stats{gap:6px}.district-stats span{font-size:7px}.district-copy p{max-width:170px}.side-column{grid-template-columns:1fr}.resources-panel{grid-column:auto}.action-panel{grid-column:auto}.bulletin-panel{grid-column:auto}.log-list{grid-template-columns:1fr 1fr}}

(() => {
  const $ = (id) => document.getElementById(id);
  const canvas = $('city-map'), ctx = canvas.getContext('2d');
  const districtData = [
    {name:'Old Harbor', type:'WATERFRONT', desc:'Salt air, old warehouses, and a tight-knit community.', color:'#63c8b7', value:2, growth:0, trust:3, rival:1},
    {name:'Market Row', type:'COMMERCE', desc:'A lively bazaar where small businesses keep the lights on.', color:'#f4b474', value:3, growth:0, trust:2, rival:2},
    {name:'Centro', type:'DOWNTOWN', desc:'The bright heart of Puerto Sol. Everyone passes through.', color:'#d5fa63', value:4, growth:1, trust:2, rival:2},
    {name:'Palm Heights', type:'RESIDENTIAL', desc:'Quiet streets, shaded courtyards, and proud neighbors.', color:'#a78ee8', value:2, growth:0, trust:4, rival:1},
    {name:'The Yards', type:'INDUSTRIAL', desc:'A hard-working district ready for a new chapter.', color:'#ed7f77', value:3, growth:0, trust:1, rival:3}
  ];
  const defaults = {week:1,cash:42,crew:5,goodwill:8,attention:16,score:0,selected:2,gameOver:false,logs:[{text:'A new season begins. Puerto Sol is full of promise.',tag:'NOW'},{text:'Neighbors are watching to see who steps up.',tag:'TODAY'}],districts:districtData.map(d=>({influence:d.growth, trust:d.trust, rival:d.rival, developed:0}))};
  let state;
  try { const saved=JSON.parse(localStorage.getItem('neon-district-save')); state=saved&&saved.districts?.length===5?{...defaults,...saved}:structuredClone(defaults); } catch { state=structuredClone(defaults); }
  let toastTimer, canvasScale=1, pulse=0;
  const money=(n)=>`${n<0?'−':''}$${Math.abs(n)}`;
  function save(){try{localStorage.setItem('neon-district-save',JSON.stringify(state));}catch{}}
  function log(text,tag='WEEK '+String(state.week).padStart(2,'0')){state.logs.unshift({text,tag});state.logs=state.logs.slice(0,4);}
  function notify(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100);}
  function render(){
    $('season-label').textContent='SEASON '+String(Math.ceil(state.week/12)).padStart(2,'0');$('week-label').textContent='WEEK '+String(((state.week-1)%12)+1).padStart(2,'0');
    const resources=[['◈','CASH',money(state.cash),''],['♟','CREW',state.crew,'members'],['✳','GOODWILL',state.goodwill,'pts']];
    $('resource-grid').innerHTML=resources.map(r=>`<div class="resource"><span class="resource-label"><i>${r[0]}</i>${r[1]}</span><div class="resource-value">${r[2]}${r[3]?`<small>${r[3]}</small>`:''}</div></div>`).join('');
    const heat=state.attention, label=heat<30?'LOW':heat<60?'NOTICEABLE':heat<82?'ELEVATED':'CRITICAL';$('heat-value').textContent=label;$('heat-value').style.color=heat<40?'var(--lime)':heat<70?'var(--orange)':'var(--red)';$('heat-meter-fill').style.width=heat+'%';$('heat-meter-fill').style.background=heat<40?'var(--lime)':heat<70?'var(--orange)':'var(--red)';
    $('district-strip').innerHTML=districtData.map((d,i)=>`<button class="district-tab ${i===state.selected?'active':''}" data-district="${i}"><strong>${d.name}</strong><span>${d.type}</span></button>`).join('');
    const i=state.selected,d=districtData[i],s=state.districts[i];$('action-context').textContent=d.type;
    $('district-detail').innerHTML=`<div class="district-copy"><strong>${d.name}</strong><p>${d.desc}</p></div><div class="district-stats"><span>YOUR REACH <b>${s.influence}</b></span><span>COMMUNITY <b>${s.trust}</b></span></div>`;
    const actions=[
      {id:'expand',icon:'↗',title:'Grow your reach',cost:'$12 · +1 crew',disabled:state.cash<12||state.crew<1},
      {id:'invest',icon:'✳',title:'Back local shops',cost:'$8 · +2 goodwill',disabled:state.cash<8},
      {id:'connect',icon:'♡',title:'Meet the neighbors',cost:'2 crew · +3 trust',disabled:state.crew<2},
      {id:'cooldown',icon:'◌',title:'Keep a low profile',cost:'$5 · −12 attention',disabled:state.cash<5}
    ];
    $('action-list').innerHTML=actions.map(a=>`<button class="action-btn" data-action="${a.id}" ${a.disabled||state.gameOver?'disabled':''}><span class="action-icon">${a.icon}</span><span class="action-text"><b>${a.title}</b><small>${a.cost}</small></span></button>`).join('');
    $('advance-btn').disabled=state.gameOver;$('advance-btn').style.opacity=state.gameOver?'.5':'1';
    $('log-list').innerHTML=state.logs.map(x=>`<div class="log-entry"><i></i><span>${x.text}</span><small>${x.tag}</small></div>`).join('');
    if(state.gameOver){$('advance-btn').innerHTML='<span>SEASON COMPLETE</span><b>✓</b>';}
    else $('advance-btn').innerHTML='<span>END WEEK</span><b>→</b>';
    save();drawMap();
  }
  function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
  function polygon(points,fill,stroke){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let p=1;p<points.length;p++)ctx.lineTo(points[p][0],points[p][1]);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
  function drawBuilding(x,y,w,h,color,seed){
    const skew=w*.34, depth=w*.28;
    // building shadow
    polygon([[x-w/2,y],[x+depth,y+depth*.45],[x+depth,y-h+depth*.45],[x-w/2,y-h]],'#0c1518a8');
    polygon([[x-w/2,y-h],[x,y-h-skew*.22],[x+depth,y-h+depth*.45],[x-w/2+depth,y-h+depth*.45]],color);
    polygon([[x-w/2,y-h],[x-w/2+depth,y-h+depth*.45],[x-w/2+depth,y+depth*.45],[x-w/2,y]],shade(color,-22));
    polygon([[x-w/2+depth,y-h+depth*.45],[x+depth,y-h+depth*.45],[x+depth,y+depth*.45],[x-w/2+depth,y+depth*.45]],shade(color,-42));
    ctx.fillStyle='#ffe2a0a8';const cols=2,rows=Math.max(2,Math.floor(h/18));for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const wx=x-w/2+depth+5+c*((w-depth-10)/cols);const wy=y-h+depth*.45+7+r*((h-depth*.45-8)/rows);if(((seed+r*3+c)%5)!==0)ctx.fillRect(wx,wy,Math.max(2,w*.055),Math.max(3,h*.045));}
    // rooftop detail
    ctx.fillStyle='#d5fa6385';ctx.fillRect(x-w*.16,y-h-2,w*.22,2);
  }
  function shade(hex,amount){const n=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(n>>16)+amount)),g=Math.max(0,Math.min(255,((n>>8)&255)+amount)),b=Math.max(0,Math.min(255,(n&255)+amount));return`rgb(${r},${g},${b})`}
  function drawTree(x,y,s){ctx.fillStyle='#101b1b';ctx.beginPath();ctx.ellipse(x+s*.15,y+s*.12,s*.48,s*.22,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#637d58';ctx.beginPath();ctx.arc(x,y-s*.45,s*.48,0,Math.PI*2);ctx.fill();ctx.fillStyle='#88a166';ctx.beginPath();ctx.arc(x-s*.15,y-s*.58,s*.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#725641';ctx.fillRect(x-1,y-s*.42,2,s*.54)}
  function drawMap(){
    if(!canvas.clientWidth)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;canvasScale=W/700;ctx.clearRect(0,0,W,H);
    const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#1c3031');grad.addColorStop(.55,'#1b2c2d');grad.addColorStop(1,'#122022');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
    // distant skyline silhouette
    for(let i=0;i<30;i++){const x=((i*71)%W),bw=16+(i*19%34),bh=22+(i*37%70);ctx.fillStyle=i%3?'#1a292b':'#203032';ctx.fillRect(x,35,bw,bh);ctx.fillStyle='#e3c36c24';for(let j=0;j<3;j++)ctx.fillRect(x+4+j*8,42+(i*j%12),2,3);}
    // distant hills
    ctx.fillStyle='#243b36';ctx.beginPath();ctx.moveTo(0,H*.39);for(let x=0;x<=W;x+=W/6)ctx.quadraticCurveTo(x+W/12,H*.27+(x%3)*3,x+W/6,H*.4);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
    const zoneW=W/5, tileW=Math.min(zoneW*.68,86*canvasScale), tileH=tileW*.42, baseY=H*.65;
    // waterfront strip
    ctx.fillStyle='#174047';ctx.fillRect(0,H*.75,W,H*.25);ctx.fillStyle='#1f5760';for(let x=10;x<W;x+=37){ctx.fillRect(x,H*.83+(x%3)*3,18,1);ctx.fillRect(x+10,H*.9,12,1)}
    for(let z=0;z<5;z++){
      const cx=zoneW*(z+.5), focus=z===state.selected, ds=state.districts[z], color=districtData[z].color;
      // elevated neighborhood base / 2x3 isometric blocks
      const points=[[cx,baseY-tileH*2.35],[cx+tileW*1.1,baseY-tileH*1.22],[cx,baseY],[cx-tileW*1.1,baseY-tileH*1.22]];
      polygon(points,focus?'#34483d':'#2b3c37',focus?color+'99':'#45544a');
      for(let gy=0;gy<3;gy++)for(let gx=0;gx<2;gx++){
        const tx=cx+(gx-gy*.5)*tileW*.55,ty=baseY-tileH*1.05+gy*tileH*.52+gx*tileH*.52;
        polygon([[tx,ty-tileH*.45],[tx+tileW*.28,ty],[tx,ty+tileH*.45],[tx-tileW*.28,ty]],(gx+gy)%2?'#34443d':'#394940','#526052');
        if((gx*3+gy+z)%4===0)drawTree(tx-tileW*.1,ty-tileH*.12,tileW*.12);
      }
      // varied city silhouette, center isometric skyline
      const heights=[[.22,.3,.2],[.35,.2,.3],[.42,.3,.23],[.25,.36,.25],[.3,.25,.39]][z];
      for(let b=0;b<3;b++){
        const bx=cx+(b-1)*tileW*.34, by=baseY-tileH*(.58+(b%2)*.48), bw=tileW*(b===1?.34:.27), bh=H*heights[b]*.47+ds.developed*2;
