  function action(id){if(state.gameOver)return;const d=state.districts[state.selected],name=districtData[state.selected].name;
    if(id==='expand'){
      if(state.cash<12||state.crew<1)return;state.cash-=12;state.crew--;d.influence++;d.developed++;state.attention=Math.min(100,state.attention+6);state.score+=2;log(`Your network found a new foothold in ${name}.`);notify(`${name}: your presence grows.`);
    }else if(id==='invest'){
      if(state.cash<8)return;state.cash-=8;state.goodwill+=2;d.trust=Math.min(10,d.trust+1);d.developed++;state.attention=Math.max(0,state.attention-2);state.score++;log(`Local shops in ${name} received a welcome boost.`);notify('Goodwill is growing.');
    }else if(id==='connect'){
      if(state.crew<2)return;state.crew-=2;d.trust=Math.min(10,d.trust+2);state.goodwill++;d.rival=Math.max(0,d.rival-1);state.attention=Math.max(0,state.attention-5);log(`A neighborhood gathering eased tensions in ${name}.`);notify('A new connection made.');
    }else if(id==='cooldown'){
      if(state.cash<5)return;state.cash-=5;state.attention=Math.max(0,state.attention-12);log('Your crew took a quiet week and let the city breathe.');notify('Attention is cooling down.');
    }
    render();
  }
  function endWeek(){
    if(state.gameOver){state.week=1;state.cash=42;state.crew=5;state.goodwill=8;state.attention=16;state.score=0;state.gameOver=false;state.districts=districtData.map(d=>({influence:d.growth,trust:d.trust,rival:d.rival,developed:0}));state.selected=2;state.logs=[];log('A fresh season begins. Puerto Sol is full of promise.','NOW');render();notify('Welcome to a new season.');return;}
    const income=4+state.districts.reduce((sum,d)=>sum+d.influence,0);state.cash+=income;state.crew=Math.min(12,state.crew+1);state.attention=Math.min(100,Math.max(0,state.attention-3+Math.floor(state.districts.reduce((sum,d)=>sum+d.influence,0)/5)));
    if(state.goodwill>=10&&Math.random()<.42){state.cash+=3;log('A neighborhood fundraiser brought a little extra support.');}
    if(state.attention>=75){state.cash=Math.max(0,state.cash-5);state.goodwill=Math.max(0,state.goodwill-1);log('City tensions are high. Everyone took a step back this week.');}
    else if(state.attention<40&&Math.random()<.35){state.goodwill++;log('A calm week helped community trust grow.');}
    // Rivals and community life add gentle variation, never remove player control.
    const target=state.districts[(state.week+1)%5];if(target.rival>0&&Math.random()<.32)target.rival--;
    state.week++;
    if((state.week-1)%12===1)log('The city has turned a new page. A season of possibility starts now.');
    if((state.week-1)%12===1){state.gameOver=true;const reach=state.districts.reduce((sum,d)=>sum+d.influence,0);const rank=reach>=14&&state.goodwill>=10?'A city legend':reach>=9?'A neighborhood name':'A promising start';log(`Season complete: ${rank}. Final reach ${reach}, goodwill ${state.goodwill}.`,'FINAL');$('modal-title').innerHTML='Season <span>complete.</span>';$('modal-backdrop').hidden=false;$('modal-backdrop').dataset.result='true';const p=$('.modal > p');p.textContent=`Your season in Puerto Sol is complete. ${rank} — you built a reach of ${reach} and earned ${state.goodwill} goodwill. Every season tells a new story.`;$('guide-start').innerHTML='START A NEW SEASON <span>↻</span>';}
    else log(`Week ${((state.week-2)%12)+1} closed. Your network earned ${money(income)} in support.`);
    render();if(state.gameOver)notify('Season complete — see your field guide.');
  }
  function openGuide(){
    $('modal-title').innerHTML='A city of <span>possibility.</span>';
    $('.modal > p').textContent='Build a neighborhood network, earn the trust of the people, and become Puerto Sol’s most influential crew. The city is yours to shape—one week at a time.';
    $('guide-start').innerHTML='LET’S PLAY <span>→</span>';$('modal-backdrop').dataset.result='false';$('modal-backdrop').hidden=false;
  }
  $('district-strip').addEventListener('click',e=>{const b=e.target.closest('[data-district]');if(!b)return;state.selected=Number(b.dataset.district);render();});
  $('action-list').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action);});
  $('advance-btn').addEventListener('click',endWeek);
  canvas.addEventListener('pointerup',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left;const index=Math.max(0,Math.min(4,Math.floor(x/r.width*5)));state.selected=index;render();});
  $('help-btn').addEventListener('click',openGuide);
  $('modal-close').addEventListener('click',()=>{$('modal-backdrop').hidden=true;});
  $('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))$('modal-backdrop').hidden=true;});
  $('guide-start').addEventListener('click',()=>{if($('modal-backdrop').dataset.result==='true')endWeek();$('modal-backdrop').hidden=true;});
  $('sound-toggle').addEventListener('click',e=>{const enabled=e.currentTarget.dataset.on!=='true';e.currentTarget.dataset.on=String(enabled);e.currentTarget.style.color=enabled?'var(--lime)':'';e.currentTarget.textContent=enabled?'♫':'♪';notify(enabled?'Sound indicators on':'Sound indicators off');});
  window.addEventListener('resize',drawMap,{passive:true});
  render();
  if(!localStorage.getItem('neon-district-intro')){openGuide();localStorage.setItem('neon-district-intro','seen');}
})();

(() => {
  const $ = (id) => document.getElementById(id);
