    if((state.week-1)%12===1){state.gameOver=true;const finalReach=state.districts.reduce((sum,d)=>sum+d.influence,0),rank=finalReach>=14&&state.goodwill>=10?'A city legend':finalReach>=9?'A neighborhood name':'A promising start';log(`Season complete: ${rank}. Final reach ${finalReach}, goodwill ${state.goodwill}.`,'FINAL');$('modal-title').innerHTML='Season <span>complete.</span>';$('modal-backdrop').hidden=false;$('modal-backdrop').dataset.result='true';$('.modal > p').textContent=`Your season in Puerto Sol is complete. ${rank} — you built a reach of ${finalReach} and earned ${state.goodwill} goodwill. Every season tells a new story.`;$('guide-start').innerHTML='START A NEW SEASON <span>↻</span>';}
